        g.deathBursts.push({x:e.x+x*Math.cos(e.angle)-y*Math.sin(e.angle),y:e.y+x*Math.sin(e.angle)+y*Math.cos(e.angle),size:largeBursts.has(i)?72+Math.random()*28:24+Math.random()*18,life:1.3,delay:.16+i*.13});
